`timescale 1ns/1ns
module Top;
    logic clk = 0;
    logic [7:0] a = 8'h01;
    logic [3:0] hi, lo, bhi, blo;
    always_ff @(posedge clk) {<< 4 {hi, lo}} <= a;
    always @(posedge clk) {<< 4 {bhi, blo}} = a;
    initial begin
        #1 clk = 1;
        #1 $display("nonblocking hi=%h lo=%h blocking hi=%h lo=%h", hi, lo, bhi, blo);
        $finish;
    end
endmodule
